function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let isProcessing = false;
  let currentAppliedModel = null;

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // モデル一覧を読み込み
  async function loadModels() {
    try {
      const models = await window.aivicApi.list(12); // 需要予測結果テーブルからモデル情報を取得
      if (models) {
        const uniqueModels = [];
        const modelVersions = new Set();

        models.forEach(result => {
          const key = result.予測モデルバージョン;
          if (key && !modelVersions.has(key)) {
            modelVersions.add(key);
            uniqueModels.push({
              id: key,
              name: `AI需要予測モデル ${key}`,
              version: key,
              accuracy: result.予測精度 || 85,
              status: Math.random() > 0.3 ? '検証完了' : '検証中'
            });
          }
        });

        currentModels = uniqueModels;
        renderModelOptions();
      }
    } catch (error) {
      console.error('モデル読み込みエラー:', error);
    }
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        currentStores = stores.filter(store => store.有効フラグ);
        renderStoreList();
      }
    } catch (error) {
      console.error('店舗読み込みエラー:', error);
    }
  }

  // モデル選択肢を描画
  function renderModelOptions() {
    const select = container.querySelector('#select-model');
    select.innerHTML = '<option value="">-- モデルを選択してください --</option>';

    currentModels.forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (v${model.version}) - 精度:${model.accuracy}%`;
      option.dataset.status = model.status;
      select.appendChild(option);
    });
  }

  // 店舗一覧を描画
  function renderStoreList() {
    const storeList = container.querySelector('#store-list');
    storeList.innerHTML = currentStores.map(store => `
      <label style="display: flex; align-items: center; gap: 8px; color: var(--text); cursor: pointer; margin-bottom: 8px;">
        <input type="checkbox" class="store-checkbox" value="${store.店舗ID}" style="margin: 0;">
        <span>${store.店舗名} (${store.店舗コード})</span>
      </label>
    `).join('');

    updateSelectedCount();
  }

  // 選択店舗数を更新
  function updateSelectedCount() {
    const checkboxes = container.querySelectorAll('.store-checkbox:checked');
    const count = checkboxes.length;
    container.querySelector('#selected-count').textContent = count;

    // 影響範囲を更新
    if (count > 0) {
      updateImpactAnalysis(count);
    }
  }

  // 影響範囲分析を更新
  function updateImpactAnalysis(storeCount) {
    const impactSection = container.querySelector('#impact-analysis');
    impactSection.classList.remove('hidden');

    container.querySelector('#impact-stores').textContent = storeCount;
    container.querySelector('#impact-products').textContent = storeCount * 150; // 店舗あたり平均150商品と仮定
    container.querySelector('#impact-time').textContent = Math.ceil(storeCount * 2.5); // 店舗あたり2.5分と仮定
  }

  // モデル詳細を表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    if (model) {
      const detailsSection = container.querySelector('#model-details');
      detailsSection.classList.remove('hidden');

      container.querySelector('#detail-name').textContent = model.name;
      container.querySelector('#detail-version').textContent = model.version;
      container.querySelector('#detail-accuracy').textContent = `${model.accuracy}%`;
      container.querySelector('#detail-status').textContent = model.status;

      // ロールバックボタンの状態を更新
      const rollbackBtn = container.querySelector('#btn-rollback');
      rollbackBtn.disabled = !currentAppliedModel;
    } else {
      container.querySelector('#model-details').classList.add('hidden');
    }
  }

  // 適用前検証を実行
  async function runValidation() {
    const modelId = container.querySelector('#select-model').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked'));

    if (!modelId) {
      alert('適用対象のモデルが選択されていません');
      return;
    }

    if (selectedStores.length === 0) {
      alert('適用対象の店舗が選択されていません');
      return;
    }

    const model = currentModels.find(m => m.id === modelId);
    if (model.status !== '検証完了') {
      alert('検証が完了していないモデルは本番適用できません');
      return;
    }

    const validationSection = container.querySelector('#validation-results');
    validationSection.classList.remove('hidden');

    const content = container.querySelector('#validation-content');
    content.innerHTML = `
      <div style="color: var(--text);">
        <div style="margin-bottom: 10px;">✓ モデル整合性チェック: 正常</div>
        <div style="margin-bottom: 10px;">✓ 店舗データ整合性: 正常</div>
        <div style="margin-bottom: 10px;">✓ システムリソース: 十分</div>
        <div style="margin-bottom: 10px;">✓ バックアップ領域: 十分</div>
        <div style="color: var(--primary); font-weight: bold;">検証結果: 適用可能</div>
      </div>
    `;

    container.querySelector('#btn-apply').disabled = false;
  }

  // モデル適用を実行
  async function applyModel() {
    const modelId = container.querySelector('#select-model').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked'));
    const startDateTime = container.querySelector('#input-start-datetime').value;
    const retentionDays = parseInt(container.querySelector('#input-retention-days').value);
    const backupEnabled = container.querySelector('#backup-enabled').checked;

    // バリデーション
    if (!modelId) {
      alert('適用対象のモデルが選択されていません');
      return;
    }

    if (selectedStores.length === 0) {
      alert('適用対象の店舗が選択されていません');
      return;
    }

    if (!startDateTime) {
      alert('適用開始日時を設定してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      alert('適用開始日時は現在日時以降を指定してください');
      return;
    }

    if (retentionDays <= 0) {
      alert('現行モデル保持期間は1日以上を設定してください');
      return;
    }

    if (isProcessing) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return;
    }

    if (!confirm(`${selectedStores.length}店舗にモデル「${modelId}」を適用します。よろしいですか？`)) {
      return;
    }

    isProcessing = true;
    container.querySelector('#btn-apply').disabled = true;
    container.querySelector('#btn-validate').disabled = true;

    // 進捗表示開始
    const progressSection = container.querySelector('#progress-section');
    progressSection.classList.remove('hidden');

    const resultSection = container.querySelector('#result-log');
    resultSection.classList.remove('hidden');

    const logContent = container.querySelector('#log-content');
    logContent.textContent = '';

    // 適用処理をシミュレート
    const steps = [
      { text: 'バックアップ作成中...', progress: 10 },
      { text: '現行モデル停止中...', progress: 25 },
      { text: '新モデル配置中...', progress: 50 },
      { text: '店舗別設定適用中...', progress: 75 },
      { text: 'サービス再開中...', progress: 90 },
      { text: '適用完了', progress: 100 }
    ];

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];

      // 進捗更新
      container.querySelector('#progress-bar').style.width = `${step.progress}%`;
      container.querySelector('#progress-text').textContent = step.text;
      container.querySelector('#progress-percent').textContent = `${step.progress}%`;

      // ログ追加
      const timestamp = new Date().toLocaleTimeString();
      logContent.textContent += `[${timestamp}] ${step.text}\n`;
      logContent.scrollTop = logContent.scrollHeight;

      // 待機
      await new Promise(resolve => setTimeout(resolve, 1000 + Math.random() * 1000));
    }

    // 適用完了処理
    currentAppliedModel = modelId;
    container.querySelector('#btn-rollback').disabled = false;
    isProcessing = false;

    alert('モデルの本番適用が完了しました');
  }

  // ロールバック実行
  async function rollbackModel() {
    if (!currentAppliedModel) {
      alert('ロールバック対象のモデルが存在しません');
      return;
    }

    if (isProcessing) {
      alert('処理実行中のため、ロールバックできません');
      return;
    }

    if (!confirm('モデルをロールバックします。よろしいですか？')) {
      return;
    }

    isProcessing = true;
    container.querySelector('#btn-rollback').disabled = true;

    // ロールバック処理をシミュレート
    const progressSection = container.querySelector('#progress-section');
    progressSection.classList.remove('hidden');

    const logContent = container.querySelector('#log-content');
    logContent.textContent = '';

    const steps = [
      { text: 'ロールバック開始...', progress: 20 },
      { text: '前バージョン復元中...', progress: 60 },
      { text: 'サービス再開中...', progress: 90 },
      { text: 'ロールバック完了', progress: 100 }
    ];

    for (const step of steps) {
      container.querySelector('#progress-bar').style.width = `${step.progress}%`;
      container.querySelector('#progress-text').textContent = step.text;
      container.querySelector('#progress-percent').textContent = `${step.progress}%`;

      const timestamp = new Date().toLocaleTimeString();
      logContent.textContent += `[${timestamp}] ${step.text}\n`;
      logContent.scrollTop = logContent.scrollHeight;

      await new Promise(resolve => setTimeout(resolve, 800));
    }

    currentAppliedModel = null;
    isProcessing = false;
    container.querySelector('#btn-apply').disabled = false;
    container.querySelector('#btn-validate').disabled = false;

    alert('ロールバックが完了しました');
  }

  // イベントリスナー設定
  container.querySelector('#select-model').addEventListener('change', (e) => {
    const modelId = e.target.value;
    if (modelId) {
      showModelDetails(modelId);
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      container.querySelector('#btn-apply').disabled = true;
    }
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateSelectedCount();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateSelectedCount();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.store-checkbox');
      const checkedCheckboxes = container.querySelectorAll('.store-checkbox:checked');
      const selectAllCheckbox = container.querySelector('#select-all-stores');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.checked = true;
        selectAllCheckbox.indeterminate = false;
      } else {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = true;
      }
    }
  });

  container.querySelector('#input-retention-days').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value === 0) {
      alert('保持期間に0日が設定されています。1日以上を設定してください。');
      e.target.focus();
    }
  });

  container.querySelector('#btn-validate').addEventListener('click', runValidation);
  container.querySelector('#btn-apply').addEventListener('click', applyModel);
  container.querySelector('#btn-rollback').addEventListener('click', rollbackModel);

  // 初期データ読み込み
  loadModels();
  loadStores();
}
